let enabled=true,li=0,mode='learn',qi=0,questions=[],busy=false,errors=0,selected=null;const heard=lessons.map(()=>new Set());let progress={};try{progress=JSON.parse(localStorage.getItem('bee-six-progress')||'{}')}catch{}const modes=[['learn','🔊 Изучай'],['match','🌸 Найди пару'],['train','🚂 Собери слово'],['read','🐝 Прочитай дорожку']];
const $=id=>document.getElementById(id);const shuffle=a=>[...a].sort(()=>Math.random()-.5);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function speak(word){if(!enabled||!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(word);u.lang='en-GB';u.rate=.78;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB'&&/Google|Microsoft|Daniel|Serena/i.test(v.name))||voices.find(v=>v.lang==='en-GB')||null;speechSynthesis.speak(u)}
function tone(ok){if(!enabled)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.setValueAtTime(ok?660:180,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(ok?990:90,ctx.currentTime+.13);g.gain.setValueAtTime(.07,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25);o.start();o.stop(ctx.currentTime+.26);o.onended=()=>ctx.close()}catch{}}
function done(m){progress[`${li}:${m}`]=true;try{localStorage.setItem('bee-six-progress',JSON.stringify(progress))}catch{}updateBadge()}
function updateBadge(){$('lessonBadge').textContent=`${modes.filter(([m])=>progress[`${li}:${m}`]).length}/4 🌼`}
function lessonLabel(i){const l=lessons[i];return l.label||`Урок ${l.number||i+1}`}
function home(){if('speechSynthesis'in window)speechSynthesis.cancel();$('home').hidden=false;$('lesson').hidden=true;const card=(l,i)=>{let n=modes.filter(([m])=>progress[`${i}:${m}`]).length;return `<button class="tile" data-lesson="${i}" style="--tint:${l.tint}"><div class="art" aria-hidden="true">${l.art}</div><div class="ribbon">${lessonLabel(i)}</div><div class="desc">${l.title}</div><div class="foot"><span class="${n?'badge':''}">${n?`${n}/4 задания пройдено`:'Заглянуть внутрь'}</span><span class="go">→</span></div></button>`};for(const [id,extra] of [['tiles',false],['extraTiles',true]]){$(id).innerHTML=lessons.map((l,i)=>Boolean(l.extra)===extra?card(l,i):'').join('');$(id).querySelectorAll('button').forEach(b=>b.onclick=()=>openLesson(+b.dataset.lesson))}}
function openLesson(i){li=i;$('home').hidden=true;$('lesson').hidden=false;$('lessonTitle').textContent=lessonLabel(i);$('sheet').src=lessons[i].sheet||`assets/lesson-${lessons[i].number||i+1}.png`;$('sheet').alt=`Рабочая тетрадь: ${lessonLabel(i)}`;document.querySelector('details').open=false;updateBadge();setMode('learn');window.scrollTo(0,0)}
function setMode(m){mode=m;busy=false;qi=0;errors=0;questions=[];selected=null;if('speechSynthesis'in window)speechSynthesis.cancel();$('tabs').innerHTML=modes.map(([k,t])=>`<button class="tab ${m===k?'active':''}" aria-pressed="${m===k}" data-mode="${k}">${lessons[li].special==='categories'&&k==='train'?'🧺 Словарные корзинки':lessons[li].special==='kSpell'&&k==='train'?'🔤 Раздели по буквам':(li===23||['ySound','shortVowels'].includes(lessons[li].special))&&k==='train'?'🔤 Раздели по звукам':li>=6&&k==='train'?'🚂 Собери фразу':t}${progress[`${li}:${k}`]?' ✓':''}</button>`).join('');$('tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));if(m==='learn')learn();else if(m==='match'){questions=shuffle(lessons[li].words);match()}else if(m==='train'){questions=shuffle(lessons[li].special==='categories'?lessons[li].words:(li===23||['ySound','kSpell','shortVowels'].includes(lessons[li].special))?lessons[li].words:li>=6?lessons[li].sentences:lessons[li].train);train()}else read()}
function header(t,desc){return `<h2>${t}</h2><p class="instructions">${desc}</p>`}
function learn(){const l=lessons[li];$('panel').innerHTML=header(l.title,'Нажимай на карточки. Слушай слово и повторяй.')+`<div class="vocab">${l.words.map((w,i)=>`<button class="wordcard ${heard[li].has(i)?'heard':''}" data-word="${i}" aria-label="Послушать ${w.word}"><span class="letters">${w.letters}</span><span class="icon" aria-hidden="true">${w.icon}</span><span class="word">${w.word}</span><span class="translation">${w.ru}</span></button>`).join('')}</div><div class="progress"><span style="width:${heard[li].size/l.words.length*100}%"></span></div><p class="hint">Прослушано: ${heard[li].size} из ${l.words.length}</p><div class="actions"><button class="primary" id="toMatch">Найди пару →</button></div><p class="notice">Озвучка зависит от английских голосов, установленных на устройстве.</p>`;$('panel').querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const i=+b.dataset.word;speak(l.words[i].word);heard[li].add(i);if(heard[li].size===l.words.length)done('learn');learn()});$('toMatch').onclick=()=>setMode('match')}
function meter(){return `<div class="progress"><span style="width:${qi/questions.length*100}%"></span></div><p class="small">Задание ${qi+1} из ${questions.length}</p>`}
function match(){if(qi>=questions.length)return result();busy=false;let w=questions[qi],others=shuffle(lessons[li].words.filter(x=>x.word!==w.word)).slice(0,2);const choices=shuffle([w,...others]);$('panel').innerHTML=header('Найди пару',li<3?'Выбери слово для буквы.':'Выбери английское слово по картинке и переводу.')+meter()+`<div class="quiz"><div class="question"><span class="big">${li<3?w.letters:w.icon}</span>${li<3?'Какое слово подходит?':w.ru}</div><div class="choices">${choices.map(x=>`<button class="choice" data-choice="${x.word}">${x.word}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('panel').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(b,b.dataset.choice===w.word,w.word));$('next').onclick=()=>{qi++;match()}}
function answer(b,ok,word){if(busy)return;if(!ok){errors++;tone(false);b.classList.add('wrong');$('feedback').textContent='Попробуй ещё раз';return}busy=true;tone(true);b.classList.add('correct');$('feedback').textContent='Верно! 🌼';$('panel').querySelectorAll('.choice').forEach(x=>x.disabled=true);$('next').hidden=false;setTimeout(()=>speak(word),260)}
function train(){if(lessons[li].special==='shortVowels')return shortVowelSort();if(lessons[li].special==='categories')return categorySort();if(lessons[li].special==='kSpell')return kSpellingSort();if(lessons[li].special==='ySound')return ySoundSort();if(li===23)return soundSort();if(li>=6)return sentenceGame();if(qi>=questions.length)return result();busy=false;const word=questions[qi];let chars,options,answerText,display;if(li<3){let idx=word.length-1;chars=word.split('');answerText=chars[idx];chars[idx]='?';options=shuffle([answerText,...shuffle('abcdefghijklmnopqrstuvwxyz'.split('').filter(x=>x!==answerText)).slice(0,2)]);display=word.slice(0,idx)+'_'}else{answerText=['sh','ch','th','ph'].find(x=>word.includes(x));chars=word.replace(answerText,'|').split('|');chars=[chars[0],'?',chars[1]].filter(x=>x);options=shuffle(['sh','ch','th','ph']);display=word.replace(answerText,'__')}
$('panel').innerHTML=header('Собери слово',li<3?'Вставь букву в пустой вагончик.':'Выбери пропущенное буквосочетание.')+meter()+`<div class="quiz"><button class="sound" id="listenTrain">🔊 Послушать слово</button><div class="train"><span class="engine" aria-hidden="true">🚂</span>${chars.map(ch=>`<span class="wagon">${ch}</span>`).join('')}</div><p class="small">${display}</p><div class="choices">${options.map(ch=>`<button class="choice" data-part="${ch}">${ch}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('listenTrain').onclick=()=>speak(word);$('panel').querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{const ok=b.dataset.part===answerText;answer(b,ok,word);if(ok){$('panel').querySelectorAll('.wagon').forEach(w=>{if(w.textContent==='?')w.textContent=answerText})}});$('next').onclick=()=>{qi++;train()}}
function read(){questions=lessons[li].read||lessons[li].train;qi=Math.min(qi,questions.length);if(qi===questions.length)return result();const word=questions[qi];$('panel').innerHTML=header('Прочитай дорожку','Прочитай вслух. Затем послушай и проверь себя.')+meter()+`<div class="quiz"><div class="garden" aria-hidden="true">🐝 · 🌼 · 🌸</div><div class="readcard">${word}</div><div><button class="sound" id="listenRead">🔊 Проверить произношение</button></div><div class="actions"><button class="primary" id="readDone">Я прочитал(а) →</button></div><p class="notice">Это самостоятельное чтение: игра не оценивает голос.</p></div>`;$('listenRead').onclick=()=>speak(word);$('readDone').onclick=()=>{tone(true);qi++;read()}}
function result(){done(mode);const name=mode==='match'?'Найди пару':mode==='train'?(lessons[li].special==='categories'?'Словарные корзинки':lessons[li].special==='kSpell'?'Раздели по буквам':(li===23||['ySound','shortVowels'].includes(lessons[li].special))?'Раздели по звукам':li>=6?'Собери фразу':'Собери слово'):'Прочитай дорожку';$('panel').innerHTML=`<div class="result"><div class="big">🌼 🐝 🌸</div><h2>Ты молодец!</h2><p>Задание «${name}» завершено.</p><p>${mode==='read'?`Прочитано слов и фраз: ${questions.length}`:`Выполнено: ${questions.length} · Повторных попыток: ${errors}`}</p><div class="actions"><button class="primary" id="again">Ещё раз</button><button class="back" id="nextGame">Следующее задание →</button></div></div>`;$('again').onclick=()=>setMode(mode);$('nextGame').onclick=()=>{let idx=modes.findIndex(([m])=>m===mode);if(idx<3)setMode(modes[idx+1][0]);else home()}}
$('back').onclick=home;$('sound').onclick=()=>{enabled=!enabled;$('sound').textContent=enabled?'🔊 Звук':'🔇 Без звука';$('sound').setAttribute('aria-pressed',String(enabled));if(!enabled&&'speechSynthesis'in window)speechSynthesis.cancel()};home();

function sentenceGame(){if(qi>=questions.length)return result();busy=false;const q=questions[qi];const full=[q.before,q.word,q.after].join(' ').replace(/ ([.!?])/g,'$1').trim();$('panel').innerHTML=header('Собери фразу','Выбери слово для пустого вагончика. Прочитай готовую фразу.')+meter()+`<div class="quiz"><p class="hint">${q.hint||'Подумай, какое слово подходит.'}</p><div class="sentence-train"><span class="engine" aria-hidden="true">🚂</span><span class="phrase-wagon">${q.before}</span><span class="phrase-wagon" id="gap">?</span><span class="phrase-wagon">${q.after}</span></div><div class="choices">${shuffle(q.options).map(w=>`<button class="choice" data-answer="${esc(w)}">${w}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('panel').querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.answer===q.word;answer(b,ok,full);if(ok)$('gap').textContent=q.word});$('next').onclick=()=>{qi++;sentenceGame()}}

function soundSort(){if(qi>=questions.length)return result();busy=false;const w=questions[qi],correct=w.word.startsWith('ch')?'ch':'c';$('panel').innerHTML=header('Раздели слова по звукам','Послушай слово и выбери звук в его начале.')+meter()+`<div class="quiz"><div class="question"><span class="big" aria-hidden="true">${w.icon}</span>${w.word}</div><button class="sound" id="listenSort">🔊 Послушать слово</button><div class="choices" style="margin-top:20px"><button class="choice" data-sound="ch">ch /tʃ/</button><button class="choice" data-sound="c">c /k/</button></div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('listenSort').onclick=()=>speak(w.word);$('panel').querySelectorAll('[data-sound]').forEach(b=>b.onclick=()=>answer(b,b.dataset.sound===correct,w.word));$('next').onclick=()=>{qi++;soundSort()}}

function categorySort(){if(qi>=questions.length)return result();busy=false;const w=questions[qi];const cats=[['School','🎒 Школа'],['Family','👪 Семья'],['Home','🏠 Дом'],['Food','🍎 Еда']];$('panel').innerHTML=header('Словарные корзинки','Прочитай слово и выбери его корзинку.')+meter()+`<div class="quiz"><div class="question"><span class="big" aria-hidden="true">${w.icon}</span>${w.word}</div><div class="choices">${cats.map(([key,label])=>`<button class="choice" data-category="${key}">${label}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('panel').querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>answer(b,b.dataset.category===w.category,w.word));$('next').onclick=()=>{qi++;categorySort()}}

function ySoundSort(){if(qi>=questions.length)return result();busy=false;const w=questions[qi];$('panel').innerHTML=header('Раздели слова по звукам','Послушай, как читается буква y: в конце слова — /ɪ/, в начале — /j/.')+meter()+`<div class="quiz"><div class="question"><span class="big" aria-hidden="true">${w.icon}</span>${w.word}</div><button class="sound" id="listenSort">🔊 Послушать слово</button><div class="choices" style="margin-top:20px"><button class="choice" data-sound="i">/ɪ/ — в конце слова</button><button class="choice" data-sound="j">/j/ — в начале слова</button></div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('listenSort').onclick=()=>speak(w.word);$('panel').querySelectorAll('[data-sound]').forEach(b=>b.onclick=()=>answer(b,b.dataset.sound===w.sound,w.word));$('next').onclick=()=>{qi++;ySoundSort()}}

function kSpellingSort(){if(qi>=questions.length)return result();busy=false;const w=questions[qi];$('panel').innerHTML=header('Раздели слова по буквам','Звук /k/ может обозначаться буквами c, k или ck. Найди их в слове и выбери корзинку.')+meter()+`<div class="quiz"><div class="question"><span class="big" aria-hidden="true">${w.icon}</span>${w.word}</div><button class="sound" id="listenSort">🔊 Послушать слово</button><div class="choices" style="margin-top:20px">${['c','k','ck'].map(s=>`<button class="choice" data-spelling="${s}">🧺 ${s} /k/</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('listenSort').onclick=()=>speak(w.word);$('panel').querySelectorAll('[data-spelling]').forEach(b=>b.onclick=()=>answer(b,b.dataset.spelling===w.spelling,w.word));$('next').onclick=()=>{qi++;kSpellingSort()}}

function shortVowelSort(){if(qi>=questions.length)return result();busy=false;const w=questions[qi];$('panel').innerHTML=header('Раздели слова по звукам','Прочитай слово. Выбери звук: /æ/ как в cat, /e/ как в bed или /ɪ/ как в fish.')+meter()+`<div class="quiz"><div class="question"><span class="big" aria-hidden="true">${w.icon}</span>${w.word}</div><button class="sound" id="listenSort">🔊 Послушать слово</button><div class="choices" style="margin-top:20px">${[['ae','/æ/'],['e','/e/'],['i','/ɪ/']].map(([v,t])=>`<button class="choice" data-vowel="${v}">🧺 ${t}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next" hidden>Дальше →</button></div>`;$('listenSort').onclick=()=>speak(w.word);$('panel').querySelectorAll('[data-vowel]').forEach(b=>b.onclick=()=>answer(b,b.dataset.vowel===w.vowel,w.word));$('next').onclick=()=>{qi++;shortVowelSort()}}
